public inherited sharing class ContactTriggerHandler {

    public static void beforeSave(List<Contact> contacts, Boolean isInsert) {
        copyAccountDefaults(contacts, isInsert);
    }

    public static void afterInsert(List<Contact> contacts) {
        applyFirstContactPhoneToAccount(contacts);
    }

    private static void copyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact contactRecord : contacts) {
            if (contactRecord.AccountId == null) {
                continue;
            }
            Boolean needsCountry = String.isBlank(contactRecord.MailingCountry);
            Boolean needsLeadSource = isInsert && String.isBlank(contactRecord.LeadSource);
            if (needsCountry || needsLeadSource) {
                accountIds.add(contactRecord.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact contactRecord : contacts) {
            Account accountRecord = accountsById.get(contactRecord.AccountId);
            if (accountRecord == null) {
                continue;
            }
            if (String.isBlank(contactRecord.MailingCountry)) {
                contactRecord.MailingCountry = accountRecord.BillingCountry;
            }
            if (isInsert && String.isBlank(contactRecord.LeadSource)) {
                contactRecord.LeadSource = accountRecord.AccountSource;
            }
        }
    }

    /**
     * When several new contacts on the same account have a phone and the account has none,
     * the first of those contacts in trigger order supplies the account phone.
     */
    private static void applyFirstContactPhoneToAccount(List<Contact> contacts) {
        Map<Id, String> firstPhoneByAccountId = new Map<Id, String>();
        for (Contact contactRecord : contacts) {
            if (contactRecord.AccountId != null
                && String.isNotBlank(contactRecord.Phone)
                && !firstPhoneByAccountId.containsKey(contactRecord.AccountId)) {
                firstPhoneByAccountId.put(contactRecord.AccountId, contactRecord.Phone);
            }
        }
        if (firstPhoneByAccountId.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account accountRecord : [
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :firstPhoneByAccountId.keySet()
        ]) {
            if (String.isBlank(accountRecord.Phone)) {
                accountsToUpdate.add(new Account(
                    Id = accountRecord.Id,
                    Phone = firstPhoneByAccountId.get(accountRecord.Id)
                ));
            }
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
