/**
 * Retrieves live FX rates through the FB_Exchange_Rates named credential.
 */
public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {
    }

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer HTTP_OK = 200;
    private static final Integer HTTP_SERVICE_UNAVAILABLE = 503;
    private static final Integer MAX_ATTEMPTS = 2;

    /**
     * Returns a rate for every normalised quote currency against the base currency.
     * Codes are trimmed and upper-cased. Invalid codes, or a null/empty quote set,
     * fail before any callout. One GET is sent, with a single identical retry on HTTP 503.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        String base = normaliseCurrency(baseCurrency);
        List<String> quotes = normaliseQuotes(quoteCurrencies);
        String symbols = String.join(quotes, ',');

        HttpResponse response;
        Integer attempt = 0;
        do {
            response = send(buildRequest(base, symbols));
            attempt++;
        } while (attempt < MAX_ATTEMPTS && response.getStatusCode() == HTTP_SERVICE_UNAVAILABLE);

        Integer statusCode = response.getStatusCode();
        if (statusCode != HTTP_OK) {
            throw new ExchangeRateException('Exchange rate request failed with status code ' + statusCode);
        }
        return parseRates(response.getBody(), quotes);
    }

    private static List<String> normaliseQuotes(Set<String> quoteCurrencies) {
        Set<String> uniqueQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            uniqueQuotes.add(normaliseCurrency(quoteCurrency));
        }
        List<String> quotes = new List<String>(uniqueQuotes);
        quotes.sort();
        return quotes;
    }

    private static String normaliseCurrency(String currencyCode) {
        if (currencyCode == null) {
            throw new ExchangeRateException('Currency code must be exactly three letters A-Z.');
        }
        String normalised = currencyCode.trim().toUpperCase();
        if (!Pattern.matches('[A-Z]{3}', normalised)) {
            throw new ExchangeRateException('Currency code must be exactly three letters A-Z.');
        }
        return normalised;
    }

    private static HttpRequest buildRequest(String base, String symbols) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT + '?base=' + base + '&symbols=' + symbols);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    private static HttpResponse send(HttpRequest request) {
        return new Http().send(request);
    }

    private static Map<String, Decimal> parseRates(String body, List<String> quotes) {
        RatePayload payload;
        try {
            payload = (RatePayload) JSON.deserialize(body, RatePayload.class);
        } catch (Exception ex) {
            throw new ExchangeRateException('Unable to parse exchange rate response.');
        }
        if (payload == null || payload.rates == null) {
            throw new ExchangeRateException('Unable to parse exchange rate response.');
        }

        Map<String, Decimal> ratesByCurrency = new Map<String, Decimal>();
        for (String quote : quotes) {
            Decimal rate = payload.rates.get(quote);
            if (rate == null) {
                throw new ExchangeRateException('No exchange rate returned for ' + quote + '.');
            }
            ratesByCurrency.put(quote, rate);
        }
        return ratesByCurrency;
    }

    private class RatePayload {
        public Map<String, Decimal> rates;
    }
}
