public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();
        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact contact : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email != null
        ]) {
            String domain = emailDomain(contact.Email);
            if (domain == null) {
                continue;
            }
            List<Contact> contacts = contactsByDomain.get(domain);
            if (contacts == null) {
                contacts = new List<Contact>();
                contactsByDomain.put(domain, contacts);
            }
            contacts.add(contact);
        }
        return contactsByDomain;
    }

    private static String emailDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        Integer separator = email.lastIndexOf('@');
        if (separator < 0 || separator >= email.length() - 1) {
            return null;
        }
        String domain = email.substring(separator + 1).trim().toLowerCase();
        return String.isBlank(domain) ? null : domain;
    }
}
