/**
 * Parses supplier free-text payment terms into net days and due dates.
 */
public with sharing class PaymentTerms {
    private static final Integer MAX_NET_DAYS = 180;
    private static final Pattern NET_DAYS = Pattern.compile(
        '^NET\\s*(\\d{1,3})$',
        Pattern.CASE_INSENSITIVE
    );

    private PaymentTerms() {
    }

    /**
     * Returns net days for supported terms.
     * Surrounding whitespace is ignored and matching is case-insensitive.
     * The original input is preserved in unsupported-terms errors.
     */
    public static Integer parseNetDays(String terms) {
        String normalized = terms == null ? null : terms.trim();
        if (normalized != null && normalized.equalsIgnoreCase('DUE ON RECEIPT')) {
            return 0;
        }
        if (normalized != null) {
            Matcher netMatcher = NET_DAYS.matcher(normalized);
            if (netMatcher.matches()) {
                Integer days = Integer.valueOf(netMatcher.group(1));
                if (days > MAX_NET_DAYS) {
                    throw new TermsOutOfRangeException('Net days out of range: ' + days);
                }
                return days;
            }
        }
        throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }

    /**
     * Returns invoiceDate plus the net days parsed from terms.
     * Throws the same terms exceptions as parseNetDays.
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        return invoiceDate.addDays(parseNetDays(terms));
    }
}
