/**
 * Injection-safe dynamic record search for the record-finder Lightning component.
 * Object and field names are resolved through describe metadata and filter values
 * are bound, so user input is never concatenated into SOQL. The query runs in
 * user mode and therefore honors the running user's sharing rules and FLS.
 */
public with sharing class RecordSearchService {
    public class SearchException extends Exception {
    }

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    @AuraEnabled
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields is null or empty.');
        }

        Schema.DescribeSObjectResult objectDescribe = resolveObject(objectApiName);
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        List<String> selectFields = new List<String>();
        Set<String> seenFields = new Set<String>();
        addSelectField(fieldMap, 'Id', selectFields, seenFields);
        for (String fieldName : fields) {
            addSelectField(fieldMap, fieldName, selectFields, seenFields);
        }

        List<String> whereClauses = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null) {
            Integer bindIndex = 0;
            for (String filterField : filters.keySet()) {
                Schema.DescribeFieldResult filterDescribe = resolveField(fieldMap, filterField);
                if (!filterDescribe.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + filterField);
                }
                String bindName = 'bind' + bindIndex;
                whereClauses.add(filterDescribe.getName() + ' = :' + bindName);
                binds.put(bindName, filters.get(filterField));
                bindIndex++;
            }
        }

        String orderByName = null;
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult orderDescribe = resolveField(fieldMap, orderByField);
            if (!orderDescribe.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + orderByField);
            }
            orderByName = orderDescribe.getName();
        }

        String soql =
            'SELECT ' +
            String.join(selectFields, ', ') +
            ' FROM ' +
            objectDescribe.getName();
        if (!whereClauses.isEmpty()) {
            soql += ' WHERE ' + String.join(whereClauses, ' AND ');
        }
        if (orderByName != null) {
            soql += ' ORDER BY ' + orderByName + ' ASC';
        }
        soql += ' LIMIT ' + maxRows;

        try {
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException expected) {
            throw expected;
        } catch (Exception ex) {
            String message = ex.getMessage();
            if (String.isBlank(message)) {
                message = 'Search failed.';
            }
            throw new SearchException(message, ex);
        }
    }

    private static Schema.DescribeSObjectResult resolveObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object does not exist.');
        }
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType = globalDescribe.get(objectApiName.toLowerCase());
        if (objectType == null) {
            objectType = globalDescribe.get(objectApiName);
        }
        if (objectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('User cannot read object: ' + objectApiName);
        }
        if (!objectDescribe.isQueryable()) {
            throw new SearchException('User cannot read object: ' + objectApiName);
        }
        return objectDescribe;
    }

    private static void addSelectField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        List<String> selectFields,
        Set<String> seenFields
    ) {
        String canonical = resolveField(fieldMap, fieldName).getName();
        String key = canonical.toLowerCase();
        if (!seenFields.contains(key)) {
            seenFields.add(key);
            selectFields.add(canonical);
        }
    }

    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('Field is not a field of the object.');
        }
        Schema.SObjectField fieldToken = fieldMap.get(fieldName.toLowerCase());
        if (fieldToken == null) {
            fieldToken = fieldMap.get(fieldName);
        }
        if (fieldToken == null) {
            throw new SearchException('Field is not a field of the object: ' + fieldName);
        }
        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException('User cannot read field: ' + fieldName);
        }
        return fieldDescribe;
    }
}
