/**
 * Invocable Flow action that finds a Contact by email.
 * Sharing of the running user is enforced. One SOQL query is used per call.
 */
public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(
            label='Email'
            description='Email address to find a Contact for.'
            required=true
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching Contact. Null when no match is found.'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True when a Contact with this email exists.'
        )
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds a Contact by email. Matching ignores case and leading or trailing spaces. If several Contacts match, the earliest CreatedDate is returned.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedByIndex = new List<String>();
        Set<String> emailsToQuery = new Set<String>();

        for (Request req : requests) {
            String normalized = normalize(req == null ? null : req.email);
            normalizedByIndex.add(normalized);
            if (normalized != null) {
                emailsToQuery.add(normalized);
            }
        }

        // Apex map keys are case-sensitive, so keys are normalized. SOQL string
        // comparison is case-insensitive. ORDER BY yields the earliest CreatedDate
        // first; Id is a deterministic tiebreaker.
        Map<String, Id> earliestContactByEmail = new Map<String, Id>();
        if (!emailsToQuery.isEmpty()) {
            for (Contact match : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalize(match.Email);
                if (key != null && !earliestContactByEmail.containsKey(key)) {
                    earliestContactByEmail.put(key, match.Id);
                }
            }
        }

        for (String normalized : normalizedByIndex) {
            Result result = new Result();
            Id contactId = normalized == null ? null : earliestContactByEmail.get(normalized);
            result.contactId = contactId;
            result.found = contactId != null;
            results.add(result);
        }
        return results;
    }

    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
