public with sharing class OrderPayloadParser {
    private static final Integer MAX_QUANTITY = 2147483647;
    private static final String ACK_STATUS = 'RECEIVED';

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {
    }

    private OrderPayloadParser() {
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Order payload is required.');
        }
        if (body.startsWith('\uFEFF')) {
            body = body.substring(1);
            if (String.isBlank(body)) {
                throw new PayloadException('Order payload is required.');
            }
        }

        try {
            JSONParser parser = JSON.createParser(body);
            if (parser.nextToken() != JSONToken.START_OBJECT) {
                throw new PayloadException('Order payload must be a JSON object.');
            }
            OrderPayloadParser.Order parsed = readOrder(parser);
            if (parser.nextToken() != null) {
                throw new PayloadException('Order payload is not valid JSON.');
            }
            return parsed;
        } catch (PayloadException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new PayloadException('Order payload is not valid JSON.');
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null || String.isBlank(order.orderNumber)) {
            throw new PayloadException('Order number is required.');
        }
        Integer lineCount = order.lines == null ? 0 : order.lines.size();
        Decimal total = order.total == null ? 0 : order.total;

        JSONGenerator generator = JSON.createGenerator(false);
        generator.writeStartObject();
        generator.writeStringField('number', order.orderNumber);
        generator.writeStringField('status', ACK_STATUS);
        generator.writeNumberField('lineCount', lineCount);
        generator.writeNumberField('total', total);
        generator.writeEndObject();
        return generator.getAsString();
    }

    private static OrderPayloadParser.Order readOrder(JSONParser parser) {
        String orderNumber;
        Boolean sawNumber = false;
        Date orderDate;
        String currencyCode;
        String customerEmail;
        List<Line> lines = new List<Line>();

        while (parser.nextToken() != JSONToken.END_OBJECT) {
            String fieldName = readFieldName(parser);
            JSONToken valueToken = nextValueToken(parser);
            if (fieldName == 'number') {
                sawNumber = true;
                orderNumber = readString(parser, valueToken, 'Order number is required.');
            } else if (fieldName == 'date') {
                orderDate = parseIsoDate(readString(parser, valueToken, 'Order date must use yyyy-MM-dd.'));
            } else if (fieldName == 'currency') {
                currencyCode = readString(parser, valueToken, 'Order payload is not valid JSON.');
            } else if (fieldName == 'customer') {
                customerEmail = readCustomerEmail(parser, valueToken);
            } else if (fieldName == 'lines') {
                lines = readLines(parser, valueToken);
            } else {
                skipValue(parser, valueToken);
            }
        }

        if (!sawNumber || String.isBlank(orderNumber)) {
            throw new PayloadException('Order number is required.');
        }

        Decimal total = 0;
        for (Line line : lines) {
            total += line.lineTotal;
        }

        OrderPayloadParser.Order parsed = new OrderPayloadParser.Order();
        parsed.orderNumber = orderNumber;
        parsed.orderDate = orderDate;
        parsed.currencyCode = currencyCode;
        parsed.customerEmail = customerEmail;
        parsed.lines = lines;
        parsed.total = total.setScale(2, System.RoundingMode.HALF_UP);
        return parsed;
    }

    private static String readCustomerEmail(JSONParser parser, JSONToken token) {
        if (token == JSONToken.VALUE_NULL) {
            return null;
        }
        if (token != JSONToken.START_OBJECT) {
            throw new PayloadException('Order payload is not valid JSON.');
        }

        String email;
        while (parser.nextToken() != JSONToken.END_OBJECT) {
            String fieldName = readFieldName(parser);
            JSONToken valueToken = nextValueToken(parser);
            if (fieldName == 'email') {
                email = readString(parser, valueToken, 'Order payload is not valid JSON.');
            } else {
                skipValue(parser, valueToken);
            }
        }
        return email;
    }

    private static List<Line> readLines(JSONParser parser, JSONToken token) {
        if (token == JSONToken.VALUE_NULL) {
            return new List<Line>();
        }
        if (token != JSONToken.START_ARRAY) {
            throw new PayloadException('Order payload is not valid JSON.');
        }

        List<Line> lines = new List<Line>();
        while (parser.nextToken() != JSONToken.END_ARRAY) {
            lines.add(readLine(parser, parser.getCurrentToken()));
        }
        return lines;
    }

    private static Line readLine(JSONParser parser, JSONToken token) {
        if (token != JSONToken.START_OBJECT) {
            throw new PayloadException('Line sku is required.');
        }

        String sku;
        Boolean sawSku = false;
        Integer quantity;
        Boolean sawQuantity = false;
        Decimal unitPrice;
        Boolean sawUnitPrice = false;
        Decimal discount = 0;

        while (parser.nextToken() != JSONToken.END_OBJECT) {
            String fieldName = readFieldName(parser);
            JSONToken valueToken = nextValueToken(parser);
            if (fieldName == 'sku') {
                sawSku = true;
                sku = readString(parser, valueToken, 'Line sku is required.');
            } else if (fieldName == 'quantity') {
                sawQuantity = true;
                quantity = readQuantity(parser, valueToken);
            } else if (fieldName == 'unitPrice') {
                sawUnitPrice = true;
                unitPrice = readUnitPrice(parser, valueToken);
            } else if (fieldName == 'discount') {
                discount = readDiscount(parser, valueToken);
            } else {
                skipValue(parser, valueToken);
            }
        }

        if (!sawSku || String.isBlank(sku)) {
            throw new PayloadException('Line sku is required.');
        }
        if (!sawQuantity || quantity == null || quantity <= 0) {
            throw new PayloadException('Line quantity must be a positive integer.');
        }
        if (!sawUnitPrice || unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Line unit price is required and cannot be negative.');
        }

        Line line = new Line();
        line.sku = sku;
        line.quantity = quantity;
        line.unitPrice = unitPrice;
        line.discount = discount == null ? 0 : discount;
        line.lineTotal = calculateLineTotal(quantity, unitPrice, line.discount);
        return line;
    }

    private static Integer readQuantity(JSONParser parser, JSONToken token) {
        Decimal raw = readNumber(parser, token, 'Line quantity must be a positive integer.');
        Decimal whole = raw.setScale(0, System.RoundingMode.DOWN);
        if (raw <= 0 || raw != whole || whole > MAX_QUANTITY) {
            throw new PayloadException('Line quantity must be a positive integer.');
        }
        return whole.intValue();
    }

    private static Decimal readUnitPrice(JSONParser parser, JSONToken token) {
        Decimal raw = readNumber(parser, token, 'Line unit price is required and cannot be negative.');
        if (raw < 0) {
            throw new PayloadException('Line unit price is required and cannot be negative.');
        }
        return raw;
    }

    private static Decimal readDiscount(JSONParser parser, JSONToken token) {
        if (token == JSONToken.VALUE_NULL) {
            return 0;
        }
        return readNumber(parser, token, 'Order payload is not valid JSON.');
    }

    private static Decimal calculateLineTotal(Integer quantity, Decimal unitPrice, Decimal discount) {
        Decimal amount = unitPrice * quantity * (1 - discount);
        // Half up so a tie on the third decimal (1.005) becomes 1.01.
        return amount.setScale(2, System.RoundingMode.HALF_UP);
    }

    private static String readFieldName(JSONParser parser) {
        if (parser.getCurrentToken() != JSONToken.FIELD_NAME) {
            throw new PayloadException('Order payload is not valid JSON.');
        }
        return parser.getText();
    }

    private static JSONToken nextValueToken(JSONParser parser) {
        JSONToken token = parser.nextToken();
        if (token == null) {
            throw new PayloadException('Order payload is not valid JSON.');
        }
        return token;
    }

    private static String readString(JSONParser parser, JSONToken token, String message) {
        if (token == JSONToken.VALUE_NULL) {
            return null;
        }
        if (token != JSONToken.VALUE_STRING) {
            throw new PayloadException(message);
        }
        return parser.getText();
    }

    private static Decimal readNumber(JSONParser parser, JSONToken token, String message) {
        if (token != JSONToken.VALUE_NUMBER_INT && token != JSONToken.VALUE_NUMBER_FLOAT) {
            throw new PayloadException(message);
        }
        return parser.getDecimalValue();
    }

    private static void skipValue(JSONParser parser, JSONToken token) {
        if (token == JSONToken.START_OBJECT || token == JSONToken.START_ARRAY) {
            parser.skipChildren();
        }
    }

    private static Date parseIsoDate(String value) {
        if (value == null) {
            return null;
        }
        if (!isIsoDateText(value)) {
            throw new PayloadException('Order date must use yyyy-MM-dd.');
        }
        try {
            Date parsed = Date.valueOf(value);
            if (parsed == null || toIsoDate(parsed) != value) {
                throw new PayloadException('Order date must use yyyy-MM-dd.');
            }
            return parsed;
        } catch (PayloadException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new PayloadException('Order date must use yyyy-MM-dd.');
        }
    }

    private static Boolean isIsoDateText(String value) {
        if (value.length() != 10 || value.substring(4, 5) != '-' || value.substring(7, 8) != '-') {
            return false;
        }
        for (Integer index = 0; index < value.length(); index++) {
            if (index == 4 || index == 7) {
                continue;
            }
            String character = value.substring(index, index + 1);
            if (character < '0' || character > '9') {
                return false;
            }
        }
        return true;
    }

    private static String toIsoDate(Date value) {
        return String.valueOf(value.year())
            + '-'
            + String.valueOf(value.month()).leftPad(2, '0')
            + '-'
            + String.valueOf(value.day()).leftPad(2, '0');
    }
