        List<Integer> statusCodes = new List<Integer>{
            100, 199, 201, 204, 301, 400, 401, 404, 418, 500, 503
        };
        String body = apiResponse(
            'CORRECTED',
            address('SHOULD NOT APPLY', 'NOWHERE', '00000', 'ZZ')
