            + String.valueOf(Crypto.getRandomLong()).replace('-', '');
        User created = new User(
            Alias = ('ow' + userSeq).left(8),
            Email = token + '@example.com',
            EmailEncodingKey = 'UTF-8',
            LastName = lastName,
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            ProfileId = running.ProfileId,
