    private static String openStage() {
        ensureStages();
        return openStageName;
    }

    private static String lostStage() {
        ensureStages();
        return lostStageName;
    }

    private static void ensureStages() {
        if (openStageName != null) {
            return;
        }
        Set<String> active = new Set<String>();
        for (Schema.PicklistEntry entry : Opportunity.StageName.getDescribe().getPicklistValues()) {
            if (entry.isActive()) {
                active.add(entry.getValue());
            }
        }
        for (String candidate : new List<String>{
            'Prospecting', 'Qualification', 'Needs Analysis', 'Negotiation/Review'
        }) {
            if (active.contains(candidate)) {
                openStageName = candidate;
                break;
            }
        }
        if (openStageName == null) {
            for (String value : active) {
                if (value != WON && value != 'Closed Lost') {
                    openStageName = value;
                    break;
                }
            }
        }
        if (openStageName == null) {
            openStageName = 'Prospecting';
        }
        lostStageName = active.contains('Closed Lost') ? 'Closed Lost' : openStageName;
    }

    private static Map<Id, List<Task>> tasksByWhat(Set<Id> whatIds) {
        Map<Id, List<Task>> byWhat = new Map<Id, List<Task>>();
        for (Id whatId : whatIds) {
            byWhat.put(whatId, new List<Task>());
        }
        for (Task taskRow : [
            SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :whatIds
        ]) {
            byWhat.get(taskRow.WhatId).add(taskRow);
        }
        return byWhat;
    }

