public with sharing class LeadImportService {
    private static final String DEFAULT_LEAD_SOURCE = 'Web';
    private static final String DUPLICATE_EMAIL_ERROR_PREFIX = 'Duplicate email in import: ';

    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        LeadImportService.ImportResult result = new LeadImportService.ImportResult();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Set<String> seenEmails = new Set<String>();
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> insertIndexes = new List<Integer>();

        for (Integer index = 0; index < leads.size(); index++) {
            Lead leadRecord = leads[index];
            if (leadRecord == null) {
                result.errorsByIndex.put(index, 'Lead cannot be null');
                continue;
            }

            if (String.isBlank(leadRecord.LeadSource)) {
                leadRecord.LeadSource = DEFAULT_LEAD_SOURCE;
            }

            String normalizedEmail = normalizeEmail(leadRecord.Email);
            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(
                        index,
                        DUPLICATE_EMAIL_ERROR_PREFIX + normalizedEmail
                    );
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            leadsToInsert.add(leadRecord);
            insertIndexes.add(index);
        }

        if (leadsToInsert.isEmpty()) {
            return result;
        }

        Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);
        for (Integer resultIndex = 0; resultIndex < saveResults.size(); resultIndex++) {
            Database.SaveResult saveResult = saveResults[resultIndex];
            Integer originalIndex = insertIndexes[resultIndex];
            if (saveResult.isSuccess()) {
                result.insertedIds.add(saveResult.getId());
                result.successCount++;
            } else {
                result.errorsByIndex.put(originalIndex, joinErrorMessages(saveResult.getErrors()));
            }
        }

        return result;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    private static String joinErrorMessages(Database.Error[] errors) {
        List<String> messages = new List<String>();
        if (errors != null) {
            for (Database.Error error : errors) {
                if (error != null && error.getMessage() != null) {
                    messages.add(error.getMessage());
                }
            }
        }
        return String.join(messages, '; ');
    }
}
