/**
 * Returns the active values of a picklist or multi-select picklist chosen at runtime.
 * Object and field API names are case-insensitive. Contract failures are always
 * reported as PicklistServiceException.
 */
public inherited sharing class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name is required.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name is required.');
        }

        Schema.DescribeSObjectResult objectDescribe = describeObject(objectApiName);
        Schema.DescribeFieldResult fieldDescribe = describePicklistField(objectDescribe, fieldApiName);

        List<Option> options = new List<Option>();
        // getPicklistValues() is already in field-definition order; skipping inactive values preserves it.
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            options.add(new Option(
                entry.getValue(),
                entry.getLabel(),
                entry.isDefaultValue() == true
            ));
        }
        return options;
    }

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        try {
            // Case-insensitive, and avoids the CPU cost of a full global describe.
            List<Schema.DescribeSObjectResult> results =
                Schema.describeSObjects(new List<String>{ objectApiName });
            if (results == null || results.isEmpty() || results[0] == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectApiName);
            }
            return results[0];
        } catch (PicklistServiceException ex) {
            throw ex;
        } catch (System.LimitException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }
    }

    private static Schema.DescribeFieldResult describePicklistField(
        Schema.DescribeSObjectResult objectDescribe,
        String fieldApiName
    ) {
        Schema.SObjectField fieldToken = findField(objectDescribe.fields.getMap(), fieldApiName);
        if (fieldToken == null) {
            throw new PicklistServiceException(
                'Field does not exist on ' + objectDescribe.getName() + ': ' + fieldApiName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != DisplayType.PICKLIST && fieldType != DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldApiName
            );
        }
        return fieldDescribe;
    }

    private static Schema.SObjectField findField(
        Map<String, Schema.SObjectField> fieldsByName,
        String fieldApiName
    ) {
        if (fieldsByName == null || fieldsByName.isEmpty()) {
            return null;
        }

        Schema.SObjectField fieldToken = fieldsByName.get(fieldApiName);
        if (fieldToken != null) {
            return fieldToken;
        }

        // Describe field maps are keyed in lowercase. Fall back to a locale-safe scan
        // so names such as INDUSTRY still resolve under locales where toLowerCase() differs.
        fieldToken = fieldsByName.get(fieldApiName.toLowerCase());
        if (fieldToken != null) {
            return fieldToken;
        }
        for (String candidate : fieldsByName.keySet()) {
            if (candidate.equalsIgnoreCase(fieldApiName)) {
                return fieldsByName.get(candidate);
            }
        }
        return null;
    }
}
