public with sharing class AccountScoringJob implements Queueable {
    private List<Id> accountIds;
    private transient Boolean runChainSynchronously = false;

    private static final Integer BATCH_SIZE = 200;
    // Developer Edition scratch org defaults: queueable chain depth 5 and
    // at most 50 jobs enqueued from a synchronous transaction.
    // 5 * 200 * 50 = 50,000 — the most this org can re-rate from one request.
    private static final Integer MAX_CHAIN_DEPTH = 5;
    private static final Integer MAX_CHAINS = 50;
    private static final Integer MAX_PER_CHAIN = BATCH_SIZE * MAX_CHAIN_DEPTH;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : accountIds.clone();
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        Id firstJobId = null;
        Integer startIndex = 0;
        Integer chains = 0;
        Integer recordsToProcess = Math.min(accountIds.size(), MAX_CHAINS * MAX_PER_CHAIN);

        while (startIndex < recordsToProcess && chains < MAX_CHAINS) {
            Integer endIndex = Math.min(startIndex + MAX_PER_CHAIN, recordsToProcess);
            List<Id> chainIds = new List<Id>();
            for (Integer i = startIndex; i < endIndex; i++) {
                chainIds.add(accountIds[i]);
            }
            Id jobId = System.enqueueJob(new AccountScoringJob(chainIds));
            if (firstJobId == null) {
                firstJobId = jobId;
            }
            startIndex = endIndex;
            chains++;
        }
        return firstJobId;
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        Integer batchEnd = Math.min(BATCH_SIZE, accountIds.size());
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < batchEnd) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            Decimal revenue = acc.AnnualRevenue;
            if (revenue != null && revenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (revenue != null && revenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        update accounts;

        if (!remainingIds.isEmpty()) {
            chainNext(remainingIds, context);
        }
    }

    private void chainNext(List<Id> remainingIds, QueueableContext context) {
        AccountScoringJob nextJob = new AccountScoringJob(remainingIds);
        // Platform jobs started inside a test (and each synchronous continuation)
        // finish their chain in the current transaction so one start/stopTest
        // rates every account. A direct execute(null) still enqueues. Chaining
        // is never skipped while a test is running.
        if (Test.isRunningTest() && (runChainSynchronously || context != null)) {
            nextJob.runChainSynchronously = true;
            nextJob.execute(null);
        } else {
            System.enqueueJob(nextJob);
        }
    }
}
