/**
 * Keeps Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c equal to
 * the sum of Amount and the count of the account's open opportunities.
 *
 * without sharing so the totals include every open opportunity and the parent
 * update is applied as system automation, not under the running user's sharing.
 * Recalculates from the database on each DML (no static "already processed" set)
 * so several DML statements in one transaction all leave the accounts correct.
 * Account updates that only copy rating onto opportunities do not change Amount,
 * IsClosed, or AccountId, so they do not re-enter the rollup and cannot recurse
 * with AccountTrigger.
 */
public without sharing class OpportunityPipelineHandler {
    public static void handle(List<Opportunity> newRecords, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = collectAccountIds(newRecords, oldMap);
        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    private static Set<Id> collectAccountIds(List<Opportunity> newRecords, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        if (newRecords == null) {
            for (Opportunity oldRecord : oldMap.values()) {
                addOpenAccount(accountIds, oldRecord);
            }
            return accountIds;
        }
        if (oldMap == null) {
            for (Opportunity newRecord : newRecords) {
                addOpenAccount(accountIds, newRecord);
            }
            return accountIds;
        }
        for (Opportunity newRecord : newRecords) {
            Opportunity oldRecord = oldMap.get(newRecord.Id);
            if (changesTotals(oldRecord, newRecord)) {
                addOpenAccount(accountIds, oldRecord);
                addOpenAccount(accountIds, newRecord);
            }
        }
        return accountIds;
    }

    private static Boolean changesTotals(Opportunity oldRecord, Opportunity newRecord) {
        return oldRecord.AccountId != newRecord.AccountId
            || oldRecord.IsClosed != newRecord.IsClosed
            || oldRecord.Amount != newRecord.Amount;
    }

    private static void addOpenAccount(Set<Id> accountIds, Opportunity opp) {
        if (opp != null && opp.AccountId != null && opp.IsClosed == false) {
            accountIds.add(opp.AccountId);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Decimal> countByAccount = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            pipelineByAccount.put(accountId, 0);
            countByAccount.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId accountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            pipelineByAccount.put(accountId, toDecimal(result.get('totalAmount')));
            countByAccount.put(accountId, toDecimal(result.get('openCount')));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal pipeline = pipelineByAccount.get(acc.Id);
            Decimal openCount = countByAccount.get(acc.Id);
            if (acc.FB_Open_Pipeline__c != pipeline || acc.FB_Open_Opportunities__c != openCount) {
                acc.FB_Open_Pipeline__c = pipeline;
                acc.FB_Open_Opportunities__c = openCount;
                accountsToUpdate.add(acc);
            }
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return 0;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
