/**
 * Nightly storage reclaim for FB_Integration_Log__c.
 *
 * Non-ERROR logs, including a blank Level__c, are deleted once they are more
 * than 30 days old. ERROR logs are kept until they are more than 180 days old.
 *
 * The scheduled run only enqueues a batch. QueryLocator plus chunked DML stays
 * inside governor limits when the log table is large. Deleted rows are then
 * removed from the recycle bin so they stop counting against data storage.
 *
 * Declared without sharing on purpose: this is a system maintenance job and
 * must purge every matching log regardless of the scheduling user's sharing.
 * Schedule it as a user who can permanently delete records (Modify All Data,
 * or equivalent hard-delete rights); emptyRecycleBin runs as that user.
 */
public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';
    private static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
        // No instance state. Cutoffs are calculated when the batch starts so a
        // job that waits in the flex queue still uses a fresh window.
    }

    /**
     * Schedules a daily 02:00 run in the scheduling user's time zone.
     * @return CronTrigger Id from System.schedule
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    public void execute(SchedulableContext sc) {
        if (isBatchAlreadyQueued()) {
            return;
        }
        Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        // != does not match null in SOQL, so blank Level__c is included explicitly.
        // Those rows follow the 30-day retention, not the ERROR retention.
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                    CreatedDate < :nonErrorCutoff
                    AND (Level__c = null OR Level__c != 'ERROR')
                )
                OR (
                    CreatedDate < :errorCutoff
                    AND Level__c = 'ERROR'
                )
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (scope.isEmpty()) {
            return;
        }

        Database.DeleteResult[] results = Database.delete(scope, false);
        List<Id> purgedIds = new List<Id>();
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                purgedIds.add(scope[i].Id);
            }
        }

        // Rows that failed (for example, row locks) stay in the table and are
        // retried on a later run. Only successfully deleted Ids are hard-deleted;
        // emptyRecycleBin throws if given an Id that is not in the recycle bin.
        if (!purgedIds.isEmpty()) {
            Database.emptyRecycleBin(purgedIds);
        }
    }

    public void finish(Database.BatchableContext bc) {
        // The nightly schedule starts the next run. Nothing to chain.
    }

    private static Boolean isBatchAlreadyQueued() {
        return [
            SELECT COUNT()
            FROM AsyncApexJob
            WHERE ApexClass.Name = 'LogPurgeJob'
                AND JobType = 'BatchApex'
                AND Status IN ('Holding', 'Queued', 'Preparing', 'Processing')
        ] > 0;
    }
}
