    private static void verifyNothingRegisteredOrCommitted(TestContext ctx) {
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.unitOfWork, ctx.mocks.never()))
            .registerDirty(fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.unitOfWork, ctx.mocks.never())).commitWork();
