    private static void verifyRegisteredThenCommitted(TestContext ctx, List<ExpectedRegistration> expected) {
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.unitOfWork, ctx.mocks.times(expected.size())))
            .registerDirty(fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.unitOfWork, ctx.mocks.times(1))).commitWork();

        fflib_InOrder inOrder = new fflib_InOrder(ctx.mocks, new List<Object>{ ctx.unitOfWork });
        for (ExpectedRegistration registration : expected) {
            ((fflib_ISObjectUnitOfWork) inOrder.verify(ctx.unitOfWork, ctx.mocks.calls(1))).registerDirty(
                fflib_Match.sObjectWith(
                    new Map<SObjectField, Object>{
                        Opportunity.Id => registration.opportunityId,
                        Opportunity.NextStep => registration.nextStep,
                        Opportunity.Description => registration.description
                    }
                )
            );
        }
        ((fflib_ISObjectUnitOfWork) inOrder.verify(ctx.unitOfWork, ctx.mocks.calls(1))).commitWork();
    }

    private static Set<Id> idsOf(List<Opportunity> opportunities) {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opp : opportunities) {
            opportunityIds.add(opp.Id);
        }
