        // Qualification: (200 * 25 / 100) = 50.00; (10 * 33 / 100) = 3.30; total 53.30
        // Proposal: (10 * 33.33 / 100) = 3.333 -> 3.33 each; 3.33 + 3.33 = 6.66 (not 6.67)
        List<Opportunity> opportunities = new List<Opportunity>{
            newOpportunity(accountId, 'Prospecting', 1000, 10),
            newOpportunity(accountId, 'Prospecting', 250.555, 50),
            newOpportunity(otherAccountId, 'Qualification', 200, 25),
            newOpportunity(otherAccountId, 'Qualification', 10, 33),
            newOpportunity(accountId, 'Proposal', 10, 33.33),
            newOpportunity(otherAccountId, 'Proposal', 10, 33.33)
        };

