public with sharing class Opportunities extends fflib_SObjectDomain {
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> opportunityRecords) {
        super(opportunityRecords);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        startFulfilmentForNewlyWon(null);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        startFulfilmentForNewlyWon(existingRecords);
    }

    private void startFulfilmentForNewlyWon(Map<Id, SObject> existingRecords) {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opportunity : (List<Opportunity>) Records) {
            if (opportunity.StageName != STAGE_CLOSED_WON) {
                continue;
            }
            if (existingRecords != null) {
                Opportunity previous = (Opportunity) existingRecords.get(opportunity.Id);
                if (previous != null && previous.StageName == STAGE_CLOSED_WON) {
                    continue;
                }
            }
            opportunityIds.add(opportunity.Id);
        }
        if (opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        fulfilmentService.startFulfilment(opportunityIds);
    }
}
