    private static void fireUpdate(List<Contact> updatedContacts, List<Contact> existingContacts) {
        Map<Id, SObject> existingById = new Map<Id, SObject>();
        for (Contact existingContact : existingContacts) {
            existingById.put(existingContact.Id, existingContact);
        }

        Test.startTest();
        fflib_SObjectDomain.Test.Database.onUpdate(updatedContacts, existingById);
        fflib_SObjectDomain.triggerHandler(Contacts.class);
        Test.stopTest();
