    private static void assertFutureBirthdateRejected(Contact contact) {
        Assert.isTrue(contact.hasErrors(), 'A birthdate after today must be rejected: ' + contact);

        Boolean foundOnBirthdate = false;
        for (Database.Error err : contact.getErrors()) {
            if (err.getMessage() == Contacts.FUTURE_BIRTHDATE && errorTargetsBirthdate(err)) {
                foundOnBirthdate = true;
                break;
            }
        }
        Assert.isTrue(
            foundOnBirthdate,
            'Expected ' + Contacts.FUTURE_BIRTHDATE + ' on Birthdate but found ' + contact.getErrors()
        );
    }

    private static void assertBirthdateAccepted(Contact contact) {
        Assert.isFalse(
            contact.hasErrors(),
            'A birthdate of today or earlier must be accepted but found ' + contact.getErrors()
        );
    }

    private static void assertDomainBirthdateErrors(Integer expectedCount) {
        Assert.areEqual(
            expectedCount,
            fflib_SObjectDomain.Errors.getAll().size(),
            'Expected one domain error per future birthdate'
        );
        for (Integer i = 0; i < expectedCount; i++) {
            Assert.areEqual(
                Contacts.FUTURE_BIRTHDATE,
                fflib_SObjectDomain.Errors.getAll()[i].message,
                'Domain error message must be Contacts.FUTURE_BIRTHDATE'
            );
            Assert.areEqual(
                Contact.Birthdate,
                ((fflib_SObjectDomain.FieldError) fflib_SObjectDomain.Errors.getAll()[i]).field,
                'Domain error must target Contact.Birthdate'
            );
        }
    }

    private static Boolean errorTargetsBirthdate(Database.Error err) {
        for (String fieldName : err.getFields()) {
            if (fieldName == 'Birthdate' || fieldName.endsWith('.Birthdate')) {
                return true;
            }
        }
        return false;
    }
