public inherited sharing class OpportunityWinService {
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Closes the given Opportunities as Closed Won and publishes one Deal_Won__e
     * per opportunity actually closed. Events are registered on the same unit of
     * work as the updates and are published only after those updates succeed, so
     * a failed save publishes nothing and the exception reaches the caller.
     * Null or empty input closes nothing.
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<SObject> opportunitiesToClose = new List<SObject>();
        List<SObject> dealWonEvents = new List<SObject>();

        for (Opportunity opportunity : OpportunitiesSelector.newInstance().selectById(opportunityIds)) {
            if (opportunity.StageName == STAGE_CLOSED_WON) {
                continue;
            }

            opportunitiesToClose.add(new Opportunity(
                Id = opportunity.Id,
                StageName = STAGE_CLOSED_WON,
                CloseDate = Date.today()
            ));
            // Deal_Won__e is Publish Immediately, so it must not be sent before
            // the update is known to have succeeded.
            dealWonEvents.add(new Deal_Won__e(
                Opportunity_Id__c = opportunity.Id,
                Amount__c = opportunity.Amount
            ));
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.registerDirty(opportunitiesToClose);
        uow.registerPublishAfterSuccessTransaction(dealWonEvents);
        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
