public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes Contact.Phone to digits and '+' for the dialer.
     * Contacts with no phone are not updated.
     * @return Id of each contact that failed to save, mapped to its first error message.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsById = new Map<Id, String>();
        if (contactIds == null || contactIds.isEmpty()) {
            return errorsById;
        }

        List<Contact> contacts = new List<Contact>();
        for (Contact contact : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]) {
            if (String.isBlank(contact.Phone)) {
                continue;
            }
            contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
            contacts.add(contact);
        }

        if (contacts.isEmpty()) {
            return errorsById;
        }

        Database.SaveResult[] results = Database.update(contacts, false, AccessLevel.USER_MODE);
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                continue;
            }
            Database.Error[] rowErrors = results[i].getErrors();
            String message = (rowErrors != null && rowErrors.size() > 0)
                ? rowErrors[0].getMessage()
                : 'Update failed';
            errorsById.put(contacts[i].Id, message);
        }
        return errorsById;
    }
}
