public with sharing class PipelineSummary {
    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Sums Opportunity.Amount for the four managed stages whose CloseDate is in
     * [fromDate, toDate], inclusive. SUM ignores null amounts. A stage with no
     * qualifying rows, or only null amounts, maps to 0, never null.
     *
     * One GROUP BY query rather than a query per stage: a loop of aggregates is
     * under the SOQL limit only while this list stays fixed, costs four times the
     * governor budget, and is rejected by static analysis.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();
        Decimal zero = 0;
        for (String stageName : STAGES) {
            totals.put(stageName, zero);
        }

        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :STAGES
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stageName = (String) result.get('StageName');
            if (!totals.containsKey(stageName)) {
                continue;
            }
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            totals.put(stageName, totalAmount == null ? zero : totalAmount);
        }

        return totals;
    }
}
