/**
 * Before-insert Case handler.
 * If the related Account.Rating is Hot, Case.Priority is set to High.
 * Every other case, including cases with no Account, keeps the Priority it was created with.
 *
 * Accounts are queried once for the whole batch. Do not move that query into the
 * case loop: Email-to-Case is one case at a time, but the ERP integration inserts
 * up to 200, and a query per case exceeds the synchronous SOQL limit (100).
 */
public class CasePriorityHandler {
    public static void beforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Rating
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Case c : newCases) {
            Account related = accountsById.get(c.AccountId);
            if (related != null && related.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
