/**
 * Pushes Accounts created in this transaction to the ERP as customers.
 *
 * Callouts are illegal in trigger context, so AccountTrigger only enqueues
 * this job. One job sends every account in the trigger batch (max 200) in a
 * single POST, which is what the ERP contract allows and what governor limits
 * require. Each customer is still identified by its 18-character salesforceId.
 * Error handling and retries are intentionally out of scope.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final String ENDPOINT = 'callout:ERP/api/customers';
    private static final Integer TIMEOUT_MS = 120000;

    private List<Customer> customers;

    public ErpCustomerSync(List<Customer> customers) {
        this.customers = customers;
    }

    public static void syncNewAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Customer> payload = new List<Customer>();
        for (Account acc : accounts) {
            payload.add(new Customer(acc));
        }
        System.enqueueJob(new ErpCustomerSync(payload));
    }

    public void execute(QueueableContext context) {
        if (customers == null || customers.isEmpty()) {
            return;
        }

        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT);
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setTimeout(TIMEOUT_MS);
        // suppressApexObjectNulls = false so a blank BillingCountry is sent as null.
        req.setBody(JSON.serialize(customers, false));

        new Http().send(req);
    }

    public class Customer {
        public String salesforceId;
        public String name;
        public String country;

        public Customer(Account acc) {
            this.salesforceId = String.valueOf(acc.Id);
            this.name = acc.Name;
            this.country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
        }
    }
}
