public with sharing class FollowUpTaskService {

    /**
     * Creates one follow-up Task for each opportunity from pipeline review.
     * A validation failure on one Task does not roll back the others.
     *
     * @param opportunityIds Opportunities to follow up on. Null and duplicates are ignored.
     * @return Opportunity Ids whose follow-up Task was not created.
     *         Empty when every task was created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        Set<Id> requestedIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                requestedIds.add(opportunityId);
            }
        }
        if (requestedIds.isEmpty()) {
            return failedOpportunityIds;
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :requestedIds
            WITH USER_MODE
        ]);

        Date activityDate = Date.today().addDays(7);
        List<Task> tasks = new List<Task>();
        for (Id opportunityId : requestedIds) {
            Opportunity opportunity = opportunitiesById.get(opportunityId);
            if (opportunity == null) {
                // Missing or not visible to the running user — no task can be created.
                failedOpportunityIds.add(opportunityId);
                continue;
            }
            tasks.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = 'Follow up: ' + opportunity.Name,
                ActivityDate = activityDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
        }

        if (tasks.isEmpty()) {
            return failedOpportunityIds;
        }

        // allOrNone = false keeps validation-rule failures on the bad row only.
        Database.SaveResult[] saveResults = Database.insert(tasks, false, AccessLevel.USER_MODE);
        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                failedOpportunityIds.add(tasks[i].WhatId);
            }
        }
        return failedOpportunityIds;
    }
}
