public with sharing class LeadContactMatcher {
    /**
     * For each lead, returns the Id of the first contact with the same email, or null.
     * Does not query or modify records. Emails are matched case-insensitively after trim;
     * blank emails never match.
     *
     * Indexed with a map (first contact wins) instead of a nested loop so a few thousand
     * leads against a few thousand contacts stays linear and inside CPU limits.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedContactIds = new List<Id>();
        if (leads == null) {
            return matchedContactIds;
        }

        Map<String, Id> contactIdByEmail = indexContactsByEmail(contacts);
        for (Lead lead : leads) {
            String emailKey = normalizeEmail(lead == null ? null : lead.Email);
            matchedContactIds.add(emailKey == null ? null : contactIdByEmail.get(emailKey));
        }
        return matchedContactIds;
    }

    private static Map<String, Id> indexContactsByEmail(List<Contact> contacts) {
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts == null) {
            return contactIdByEmail;
        }
        for (Contact contact : contacts) {
            if (contact == null) {
                continue;
            }
            String emailKey = normalizeEmail(contact.Email);
            if (emailKey != null && !contactIdByEmail.containsKey(emailKey)) {
                contactIdByEmail.put(emailKey, contact.Id);
            }
        }
        return contactIdByEmail;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
