/**
 * Creates a CSAT survey Task for each Case that has just closed and still has a Contact.
 * Partial success is intentional: a failure on one Task must not roll back the others.
 * Callouts, if added for the vendor survey, must run before the Task DML.
 */
public without sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {
    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null ? new List<Id>() : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        Date activityDate = Date.today().addDays(2);
        List<Task> surveyTasks = new List<Task>();
        for (Case closedCase : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
            AND IsClosed = TRUE
            AND ContactId != NULL
        ]) {
            surveyTasks.add(new Task(
                WhatId = closedCase.Id,
                WhoId = closedCase.ContactId,
                Subject = 'CSAT survey: ' + closedCase.CaseNumber,
                ActivityDate = activityDate,
                Status = 'Not Started'
            ));
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        // Do not throw after this insert: a later exception would roll back the successes.
        Database.SaveResult[] results = Database.insert(surveyTasks, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                continue;
            }
            for (Database.Error err : results[i].getErrors()) {
                System.debug(
                    LoggingLevel.ERROR,
                    'CSAT survey Task insert failed for Case ' + surveyTasks[i].WhatId
                    + ' (' + err.getStatusCode() + '): ' + err.getMessage()
                );
            }
        }
    }
}
