```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_TERM_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    _debounceTimer;
    _requestId = 0;
    _connected = false;
    _latestTerm = '';

    connectedCallback() {
        this._connected = true;
    }

    disconnectedCallback() {
        this._connected = false;
        this._cancelPendingSearch();
        // Invalidate in-flight responses so they cannot update a removed component.
        this._requestId += 1;
    }

    handleChange(event) {
        const searchTerm = (event.detail.value || '').trim();
        this._latestTerm = searchTerm;
        this._cancelPendingSearch();

        if (searchTerm.length < MIN_TERM_LENGTH) {
            this.contacts = [];
            this.error = undefined;
            // Ignore any response already in flight.
            this._requestId += 1;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            // Component was removed while this search was still pending.
            if (!this._connected) {
                return;
            }
            const term = this._latestTerm;
            if (term.length < MIN_TERM_LENGTH) {
                return;
            }
            this._runSearch(term);
        }, DEBOUNCE_DELAY);
    }

    _cancelPendingSearch() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }

    async _runSearch(searchTerm) {
        const requestId = ++this._requestId;
        try {
            const result = await searchContacts({ searchTerm });
            if (!this._isLatestRequest(requestId)) {
                return;
            }
            this.contacts = result || [];
            this.error = undefined;
        } catch (error) {
            if (!this._isLatestRequest(requestId)) {
                return;
            }
            this.contacts = [];
            this.error = error;
        }
    }

    _isLatestRequest(requestId) {
        return this._connected && requestId === this._requestId;
    }
}
