import favoriteAdd from '@salesforce/label/c.Favorite_Add';
import favoriteRemove from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle that marks a record as a favourite.
 * `favorite` is owned by the parent; clicks update the displayed state
 * optimistically and notify the parent via `favoritechange`.
 */
export default class FavoriteToggle extends LightningElement {
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        // Parent value always wins, including after a server refresh.
        this._favorite = value === true || value === 'true';
