    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    /**
     * Label of the action a click will perform, not a description of current state.
     */
    get actionLabel() {
        return this._favorite ? favoriteRemove : favoriteAdd;
    }

    get buttonClass() {
        const base = 'slds-button slds-button_icon';
        return this._favorite
            ? `${base} slds-button_icon-brand`
            : `${base} slds-button_icon-border-filled`;
    }

    handleClick() {
        const favorite = !this._favorite;
        this._favorite = favorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite }
            })
        );
    }
}
