import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasStats = false;
    hasError = false;

    _pollTimer = null;
    _inFlight = false;
    _isConnected = false;
    _listening = false;
    _requestToken = 0;

    _handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
            return;
        }
        this.startPolling();
    };

    connectedCallback() {
        this._isConnected = true;
        if (!this._listening) {
            document.addEventListener('visibilitychange', this._handleVisibilityChange);
            this._listening = true;
        }
        this.startPolling();
    }

    disconnectedCallback() {
        this._isConnected = false;
        // Drop any response still in flight so a later insert starts clean.
        this._requestToken += 1;
        this._inFlight = false;
        this.stopPolling();
        if (this._listening) {
            document.removeEventListener('visibilitychange', this._handleVisibilityChange);
            this._listening = false;
        }
    }

    startPolling() {
        if (!this._isConnected || document.visibilityState === 'hidden') {
            return;
        }
        // Guarantee a single loop if start is invoked again.
        this.stopPolling();
        this.loadStats();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._pollTimer = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._pollTimer != null) {
            clearInterval(this._pollTimer);
            this._pollTimer = null;
        }
    }

    async loadStats() {
        if (!this._isConnected || document.visibilityState === 'hidden' || this._inFlight) {
            return;
        }
        this._inFlight = true;
        const token = ++this._requestToken;
        try {
            const stats = await getQueueStats();
            if (!this._isCurrentRequest(token)) {
                return;
            }
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            this.hasError = false;
            this.errorMessage = undefined;
        } catch (error) {
            if (!this._isCurrentRequest(token)) {
                return;
            }
            this.errorMessage = error && error.body ? error.body.message : undefined;
            this.hasError = true;
        } finally {
            if (token === this._requestToken) {
                this._inFlight = false;
            }
        }
    }

    _isCurrentRequest(token) {
        return this._isConnected && token === this._requestToken;
    }
}
