import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        this[event.target.dataset.field] = event.detail.value;
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');
        const domain = this.getEmailDomain(this.email);

        if (PERSONAL_EMAIL_DOMAINS.has(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        const inputs = this.template.querySelectorAll('lightning-input');
        let allValid = true;
        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        const { fullName, email, company } = this;
        try {
            await register({ fullName, email, company });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }

    getEmailDomain(email) {
        const value = email || '';
        const atIndex = value.lastIndexOf('@');
        if (atIndex === -1) {
            return '';
        }
        return value.slice(atIndex + 1).toLowerCase();
    }
}
