     * is shown and the active option moves to that value (or the first option
     * when nothing is selected).
     */
    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this._activeValue = value;
        this._activeOverridden = false;
    }

    get renderedOptions() {
        const selectedValue = this._value;
        return this._options.map((option, index) => ({
            id: this._optionId(index),
            value: option.value,
            label: option.label,
            index: String(index),
            ariaSelected: option.value === selectedValue ? 'true' : 'false'
        }));
    }

    get activeDescendantId() {
        const index = this.activeIndex;
        return index < 0 ? null : this._optionId(index);
    }

    /**
     * Highlighted option: the option the user moved to, otherwise the
     * selected option, otherwise the first option.
     */
    get activeIndex() {
        if (this._options.length === 0) {
            return -1;
        }
        if (this._activeOverridden) {
            const highlighted = this._indexOfValue(this._activeValue);
            if (highlighted >= 0) {
                return highlighted;
            }
        }
        const selected = this._indexOfValue(this._value);
        return selected >= 0 ? selected : 0;
    }

    handleKeydown(event) {
        const { key } = event;
        if (!HANDLED_KEYS.has(key)) {
            return;
        }
        event.preventDefault();

        const length = this._options.length;
        if (length === 0) {
            return;
        }

        if (key === 'Enter' || key === ' ') {
            this._selectByIndex(this.activeIndex);
            return;
        }

        const current = this.activeIndex;
        let next = current;
        if (key === 'ArrowDown') {
            next = Math.min(current + 1, length - 1);
        } else if (key === 'ArrowUp') {
            next = Math.max(current - 1, 0);
        } else if (key === 'Home') {
            next = 0;
        } else if (key === 'End') {
            next = length - 1;
        }
        this._setActiveIndex(next);
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        if (!Number.isInteger(index) || index < 0 || index >= this._options.length) {
            return;
        }
        this._selectByIndex(index);
        // Pointer interaction must not move DOM focus onto the option.
        const listbox = this.template.querySelector('ul[role="listbox"]');
        if (listbox) {
            listbox.focus();
        }
    }

    _optionId(index) {
        return `${this._instanceId}-option-${index}`;
    }

    _indexOfValue(value) {
        return this._options.findIndex((option) => option.value === value);
    }

    _setActiveIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        this._activeValue = option.value;
        this._activeOverridden = true;
    }

    _selectByIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        const nextValue = option.value;
        this._activeValue = nextValue;
        this._activeOverridden = true;
        if (nextValue === this._value) {
            return;
        }
        this._value = nextValue;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: nextValue }
            })
        );
    }
}
