import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    items = [];
    newLabel = '';
    nextId = 1;
    _tasks = [];

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        // Keep the parent's array and task objects intact; render from a copy.
        this._tasks = value;
        const source = Array.isArray(value) ? value : [];
        this.items = source.map((task) => ({ ...task }));
    }

    get displayHeading() {
        return this.heading == null ? '' : String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const input = this.template.querySelector('lightning-input.new-task');
        const typed = this.newLabel || (input ? input.value : '');
        const label = (typed || '').trim();
        if (!label) {
            return;
        }

        // Reassign so LWC notices the new row. Never push onto the parent's array.
        this.items = [
            ...this.items,
            { id: this.generateId(), label, done: false }
        ];
        this.newLabel = '';

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const input = event.currentTarget;
        const id = input.dataset.id;
        // dataset values are strings; compare loosely and copy so the parent
        // object is not mutated and the remaining count re-renders.
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: input.checked } : task
        );
    }

    generateId() {
        const existing = new Set(this.items.map((task) => String(task.id)));
        let id = `new-${this.nextId++}`;
        while (existing.has(id)) {
            id = `new-${this.nextId++}`;
        }
        return id;
    }
}
