/**
 * Sets each contact's current employer as a Current, primary NPSP affiliation.
 *
 * Inserting a new primary Affiliation is NPSP's standard mechanism. Affiliation
 * TDTM then marks the previous primary affiliation Former and non-primary, sets
 * its end date to today, and points Contact.npsp__Primary_Affiliation__c at the
 * organization. Contact.AccountId is never updated, so household membership is
 * preserved.
 */
public with sharing class EmployerService {
    private static final String STATUS_CURRENT = 'Current';

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Map<Id, Id> desiredOrgByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id organizationId = employerByContactId.get(contactId);
            if (contactId != null && organizationId != null) {
                desiredOrgByContactId.put(contactId, organizationId);
            }
        }
        if (desiredOrgByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = desiredOrgByContactId.keySet();
        Set<Id> organizationIds = new Set<Id>(desiredOrgByContactId.values());

        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        // Primary affiliation already pointing at the requested organization.
        // Used only to avoid inserting a duplicate; NPSP owns former-employer updates.
        Set<Id> alreadyPrimaryContactIds = new Set<Id>();
        for (npe5__Affiliation__c affiliation : [
            SELECT npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
                AND npe5__Organization__c IN :organizationIds
                AND npe5__Primary__c = TRUE
        ]) {
            if (affiliation.npe5__Organization__c == desiredOrgByContactId.get(affiliation.npe5__Contact__c)) {
                alreadyPrimaryContactIds.add(affiliation.npe5__Contact__c);
            }
        }

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        for (Id contactId : desiredOrgByContactId.keySet()) {
            if (!contactsById.containsKey(contactId)) {
                continue;
            }

            Id organizationId = desiredOrgByContactId.get(contactId);
            if (contactsById.get(contactId).npsp__Primary_Affiliation__c == organizationId
                || alreadyPrimaryContactIds.contains(contactId)) {
                continue;
            }

            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = organizationId,
                npe5__Status__c = STATUS_CURRENT,
                npe5__Primary__c = true,
                npe5__StartDate__c = Date.today()
            ));
        }

        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
