/**
 * Stages website gifts as NPSP Data Import records and processes them through
 * NPSP Data Importer (BDI) so contact matching, household creation, and donation
 * rules come from the org's Data Import settings. Each staged record is left in
 * the org as the audit trail of the import.
 */
public with sharing class GiftImportService {

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONATION_DONOR_CONTACT1 = 'Contact1';
    private static final String PREFERRED_EMAIL_PERSONAL = 'Personal';

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    /**
     * Inserts one NPSP Data Import row per gift and processes those rows
     * synchronously, in this transaction, via NPSP's Data Import Apex API.
     * The no-config API applies npsp__Data_Import_Settings__c (contact match on
     * first name, last name, and email; do not match existing donations).
     * A row NPSP rejects is marked Failed and does not stop the rest.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        List<ImportResult> results = new List<ImportResult>();
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            if (gift == null) {
                results.add(failedResult('A gift is required.'));
                continue;
            }
            results.add(null);
            staged.add(toDataImport(gift));
            stagedIndexes.add(i);
        }

        if (staged.isEmpty()) {
            return results;
        }

        insert as user staged;

        Set<Id> dataImportIds = new Set<Id>();
        for (npsp__DataImport__c dataImport : staged) {
            dataImportIds.add(dataImport.Id);
        }

        npsp.BDI_DataImport_API.processDataImportRecords(dataImportIds);

        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                npsp__Status__c,
                npsp__Contact1Imported__c,
                npsp__DonationImported__c,
                npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImportIds
            WITH USER_MODE
        ]);

        for (Integer i = 0; i < staged.size(); i++) {
            results[stagedIndexes[i]] = toImportResult(processedById.get(staged[i].Id));
        }
        return results;
    }

    private static npsp__DataImport__c toDataImport(WebGift gift) {
        npsp__DataImport__c dataImport = new npsp__DataImport__c();
        dataImport.npsp__Contact1_Firstname__c = gift.firstName;
        dataImport.npsp__Contact1_Lastname__c = gift.lastName;
        dataImport.npsp__Contact1_Personal_Email__c = gift.email;
        // Preferred Email = Personal copies this address to Contact.Email so the
        // org's first name / last name / email match rule can find the donor.
        if (String.isNotBlank(gift.email)) {
            dataImport.npsp__Contact1_Preferred_Email__c = PREFERRED_EMAIL_PERSONAL;
        }
        dataImport.npsp__Donation_Amount__c = gift.amount;
        dataImport.npsp__Donation_Date__c = gift.giftDate;
        dataImport.npsp__Donation_Donor__c = DONATION_DONOR_CONTACT1;
        return dataImport;
    }

    private static ImportResult toImportResult(npsp__DataImport__c dataImport) {
        ImportResult result = new ImportResult();
        if (dataImport == null) {
            result.success = false;
            result.errorMessage = 'NPSP Data Import record was not processed.';
            return result;
        }
        result.success = dataImport.npsp__Status__c == STATUS_IMPORTED;
        result.contactId = dataImport.npsp__Contact1Imported__c;
        result.opportunityId = dataImport.npsp__DonationImported__c;
        if (!result.success) {
            result.errorMessage = dataImport.npsp__FailureInformation__c;
        }
        return result;
    }

    private static ImportResult failedResult(String message) {
        ImportResult result = new ImportResult();
        result.success = false;
        result.errorMessage = message;
        return result;
    }
}
