/**
 * Records monthly Enhanced Recurring Donation sign-ups.
 * Inserts npe03__Recurring_Donation__c only; NPSP creates installment Opportunities.
 */
public with sharing class RecurringGiftService {
    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final String STATUS_ACTIVE = 'Active';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String OPEN_ENDED_STATUS_NONE = 'None';
    private static final String DAY_OF_MONTH_LAST_DAY = 'Last_Day';
    private static final Integer LAST_DAY_OF_MONTH = 31;

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        validate(requests);

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest request : requests) {
            donations.add(toRecurringDonation(request));
        }

        // Single DML. NPSP Enhanced Recurring Donations generates the installments.
        insert donations;

        List<Id> donationIds = new List<Id>();
        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }
        return donationIds;
    }

    private static void validate(List<GiftRequest> requests) {
        for (Integer index = 0; index < requests.size(); index++) {
            GiftRequest request = requests[index];
            if (request == null) {
                throw new RecurringGiftException('Gift request at index ' + index + ' is required.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException('Gift request at index ' + index + ' requires a contact.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException('Gift request at index ' + index + ' requires a positive amount.');
            }
            if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'Gift request at index ' + index + ' requires a day of month from 1 to 31.'
                );
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Gift request at index ' + index + ' requires a start date.');
            }
        }
    }

    private static npe03__Recurring_Donation__c toRecurringDonation(GiftRequest request) {
        Boolean openEnded = request.installments == null || request.installments == 0;
        // 31 is ERD's Last Day option, not the day value "31". 29 and 30 stay those days.
        String dayOfMonth = request.dayOfMonth == LAST_DAY_OF_MONTH
            ? DAY_OF_MONTH_LAST_DAY
            : String.valueOf(request.dayOfMonth);

        npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c(
            Name = 'Monthly Donation',
            npe03__Contact__c = request.contactId,
            npe03__Amount__c = request.amount,
            npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
            npsp__InstallmentFrequency__c = 1,
            npsp__Day_of_Month__c = dayOfMonth,
            npsp__Always_Use_Last_Day_Of_Month__c = false,
            npsp__StartDate__c = request.startDate,
            npe03__Date_Established__c = request.startDate,
            npsp__Status__c = STATUS_ACTIVE,
            npsp__PaymentMethod__c = request.paymentMethod,
            npsp__RecurringType__c = openEnded ? RECURRING_TYPE_OPEN : RECURRING_TYPE_FIXED,
            npe03__Open_Ended_Status__c = openEnded ? OPEN_ENDED_STATUS_OPEN : OPEN_ENDED_STATUS_NONE
        );
        if (!openEnded) {
            donation.npe03__Installments__c = request.installments;
        }
        return donation;
    }
}
