public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces the Opportunity's GAU allocations with one percent-based allocation
     * per map entry. Keys are General Accounting Unit Ids. Values are percentages
     * where 60 means 60%.
     *
     * Amount is left unset so NPSP treats each row as percent-based and
     * recalculates Amount when Opportunity.Amount changes. A $1,000 gift split
     * 60/40 therefore becomes $1,200 and $800 when the Opportunity is corrected
     * to $2,000, with no further code.
     *
     * A total below 100% is allowed. The remainder stays unallocated.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        validate(opportunityId, percentByGauId);

        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            AND npsp__Payment__c = null
            WITH USER_MODE
        ];

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            // Do not set npsp__Amount__c. Setting only Percent is what keeps the
            // allocation percent-based across later Opportunity amount changes.
            allocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        Savepoint sp = Database.setSavepoint();
        try {
            if (!existing.isEmpty()) {
                delete as user existing;
            }
            insert as user allocations;
        } catch (Exception ex) {
            Database.rollback(sp);
            throw ex;
        }
        return allocations;
    }

    private static void validate(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }
        if (opportunityId == null || opportunityId.getSobjectType() != Opportunity.SObjectType) {
            throw new AllocationException('A valid Opportunity Id is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null || gauId.getSobjectType() != npsp__General_Accounting_Unit__c.SObjectType) {
                throw new AllocationException('Each key must be a General Accounting Unit Id.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('Each percentage must be greater than 0.');
            }
            totalPercent += percent;
        }
        if (totalPercent > 100) {
            throw new AllocationException('Percentages must not add up to more than 100.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
            WITH USER_MODE
        ]);
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null || gau.npsp__Active__c != true) {
                throw new AllocationException('Each GAU must be active.');
            }
        }

        Integer opportunityCount = [
            SELECT COUNT()
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
        ];
        if (opportunityCount == 0) {
            throw new AllocationException('Opportunity not found.');
        }
    }
}
