/**
 * Registers a family into one NPSP Household Account.
 * NPSP creates the Household Account (record type HH_Account), names it, and
 * generates greetings. This service never sets Account.Name.
 */
public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RT_DEVELOPER_NAME = 'HH_Account';

    private HouseholdService() {
    }

    /**
     * Inserts new Contacts so they all belong to one new NPSP Household Account.
     * The first Contact in the list is the household primary contact.
     *
     * @param members New Contacts (no Id, no AccountId). Must not be null or empty.
     * @return Id of the Household Account every member belongs to.
     * @throws IllegalArgumentException if members is null or empty, or if NPSP
     *         does not create a Household Account for the primary Contact.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        // Resolve up front so a missing record type fails before any DML.
        Id householdRecordTypeId = householdRecordTypeId();

        // Insert the primary Contact alone with no Account. In the Household
        // Account model NPSP creates exactly one Household Account, names it,
        // generates greetings, and links this Contact as the initial primary.
        Contact primaryContact = members[0];
        primaryContact.AccountId = null;
        insert primaryContact;

        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ].AccountId;
        if (householdId == null) {
            throw new IllegalArgumentException(
                'NPSP did not create a household account for the primary contact.'
            );
        }
        primaryContact.AccountId = householdId;

        // Remaining members must already point at that household. Inserting them
        // with a null AccountId would make NPSP create one extra household each.
        if (members.size() > 1) {
            List<Contact> additionalMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdId;
                additionalMembers.add(member);
            }
            insert additionalMembers;
        }

        // Last write wins: keep the Household record type (looked up, not a
        // hard-coded Id) and force the first Contact to be primary. Name and
        // greeting fields are left for NPSP automatic household naming.
        update new Account(
            Id = householdId,
            RecordTypeId = householdRecordTypeId,
            npe01__One2OneContact__c = primaryContact.Id
        );

        return householdId;
    }

    /**
     * @return Household Account record type Id for DeveloperName HH_Account.
     */
    private static Id householdRecordTypeId() {
        Schema.RecordTypeInfo recordTypeInfo = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_RT_DEVELOPER_NAME);
        if (recordTypeInfo == null) {
            throw new IllegalArgumentException(
                'Household Account record type HH_Account was not found.'
            );
        }
        return recordTypeInfo.getRecordTypeId();
    }
}
