public with sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    private static final Integer CURRENCY_SCALE = 2;

    /**
     * Replaces an open pledge's unpaid, non-written-off payments with a monthly
     * installment schedule. Paid and written-off payments are left unchanged.
     * New payment amounts sum exactly to the outstanding opportunity amount.
     *
     * @param opportunityId Opportunity to reschedule. Must be open.
     * @param numberOfPayments Number of new unpaid payments. Must be at least 1.
     * @param firstPaymentDate Scheduled date of installment 0. Later dates are monthly.
     * @return Inserted payments in schedule order.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity Id is required.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('First payment date is required.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed,
                (
                    SELECT Id,
                        npe01__Payment_Amount__c,
                        npe01__Paid__c,
                        npe01__Written_Off__c
                    FROM npe01__OppPayment__r
                )
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity was not found or is not accessible.');
        }

        Opportunity opportunity = opportunities[0];
        if (opportunity.IsClosed) {
            throw new PaymentPlanException('Installments cannot be scheduled on a closed opportunity.');
        }

        Decimal preservedAmount = 0;
        List<npe01__OppPayment__c> paymentsToReplace = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c payment : opportunity.npe01__OppPayment__r) {
            if (payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true) {
                preservedAmount += payment.npe01__Payment_Amount__c == null
                    ? 0
                    : payment.npe01__Payment_Amount__c;
            } else {
                paymentsToReplace.add(payment);
            }
        }

        Decimal opportunityAmount = opportunity.Amount == null ? 0 : opportunity.Amount;
        Decimal outstanding = opportunityAmount - preservedAmount;
        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        Decimal baseAmount = outstanding.divide(
            Decimal.valueOf(numberOfPayments),
            CURRENCY_SCALE,
            System.RoundingMode.DOWN
        );
        Decimal lastAmount = outstanding - (baseAmount * (numberOfPayments - 1));

        List<npe01__OppPayment__c> installments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            installments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunity.Id,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastAmount : baseAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        Savepoint sp = Database.setSavepoint();
        try {
            if (!paymentsToReplace.isEmpty()) {
                Database.delete(paymentsToReplace, AccessLevel.USER_MODE);
            }
            Database.insert(installments, AccessLevel.USER_MODE);
        } catch (Exception ex) {
            Database.rollback(sp);
            throw ex;
        }
        return installments;
    }
}
