/**
 * Records a gift that has already been received as a Closed Won NPSP donation.
 *
 * Household Account model and Payments automation would otherwise create contact
 * roles and payments on insert. Those automations are suppressed on the gift, and
 * the children are normalized so the donor has one Donor role, every other
 * household member has one Household Member role, and the gift has one paid payment.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final String DONATION_RECORD_TYPE = 'Donation';

    /**
     * Records a Closed Won donation of {@code amount} from the contact, closed on
     * {@code giftDate}, and returns the Opportunity Id.
     *
     * @throws IllegalArgumentException if the contact does not exist, the contact has
     *         no household account, {@code amount} is null, zero, or negative, or
     *         {@code giftDate} is null.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInputs(contactId, amount, giftDate);

        Contact donor = queryDonor(contactId);
        GiftWriter writer = new GiftWriter();
        Set<Id> householdContactIds = writer.householdContactIds(donor.AccountId);

        Opportunity gift = buildGift(donor, amount, giftDate);
        insert gift;

        writer.normalize(gift.Id, donor.Id, householdContactIds, amount, giftDate);
        correctOpportunityHeader(gift.Id, donor, amount, giftDate);
        // Header correction can re-fire NPSP automation. Normalize again so the
        // saved gift still has one role per contact and exactly one payment.
        writer.normalize(gift.Id, donor.Id, householdContactIds, amount, giftDate);
        applyOpportunityName(gift.Id, donor, giftDate);

        return gift.Id;
    }

    private static void validateInputs(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null || contactId.getSObjectType() != Contact.SObjectType) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
    }

    private static Contact queryDonor(Id contactId) {
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (donors[0].AccountId == null) {
            throw new IllegalArgumentException('Contact does not belong to a household account.');
        }
        return donors[0];
    }

    private static Opportunity buildGift(Contact donor, Decimal amount, Date giftDate) {
        Opportunity gift = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npe01__Do_Not_Automatically_Create_Payment__c = true,
            npsp__DisableContactRoleAutomation__c = true
        );
        Id donationRecordTypeId = donationRecordTypeId();
        if (donationRecordTypeId != null) {
            gift.RecordTypeId = donationRecordTypeId;
        }
        return gift;
    }

    private static Id donationRecordTypeId() {
        Schema.RecordTypeInfo info = Schema.SObjectType.Opportunity
            .getRecordTypeInfosByDeveloperName()
            .get(DONATION_RECORD_TYPE);
        if (info == null || !info.isActive()) {
            return null;
        }
        return info.getRecordTypeId();
    }

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String who = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;
        return who + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Puts amount, stage, close date, household, and primary contact back if an
     * NPSP trigger rewrote them. The required name is applied separately, after
     * child normalization, because NPSP naming recalculates when these inputs change.
     */
    private static void correctOpportunityHeader(
        Id opportunityId,
        Contact donor,
        Decimal amount,
        Date giftDate
    ) {
        Opportunity current = [
            SELECT Amount, CloseDate, StageName, AccountId, npsp__Primary_Contact__c,
                   npe01__Do_Not_Automatically_Create_Payment__c,
                   npsp__DisableContactRoleAutomation__c
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        Opportunity header = new Opportunity(Id = opportunityId);
        Boolean changed = false;
        if (current.Amount != amount) {
            header.Amount = amount;
            changed = true;
        }
        if (current.CloseDate != giftDate) {
            header.CloseDate = giftDate;
            changed = true;
        }
        if (current.StageName != STAGE_CLOSED_WON) {
            header.StageName = STAGE_CLOSED_WON;
            changed = true;
        }
        if (current.AccountId != donor.AccountId) {
            header.AccountId = donor.AccountId;
            changed = true;
        }
        if (current.npsp__Primary_Contact__c != donor.Id) {
            header.npsp__Primary_Contact__c = donor.Id;
            changed = true;
        }
        if (current.npe01__Do_Not_Automatically_Create_Payment__c != true) {
            header.npe01__Do_Not_Automatically_Create_Payment__c = true;
            changed = true;
        }
        if (current.npsp__DisableContactRoleAutomation__c != true) {
            header.npsp__DisableContactRoleAutomation__c = true;
            changed = true;
        }
        if (changed) {
            update header;
        }
    }

    /**
     * Forces the required name. NPSP opportunity naming is skipped for this update
     * so a name-only correction cannot be overwritten or create another payment or role.
     */
    private static void applyOpportunityName(Id opportunityId, Contact donor, Date giftDate) {
        String desiredName = buildOpportunityName(donor, giftDate);
        Opportunity current = [
            SELECT Name
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (current.Name == desiredName) {
            return;
        }

        Boolean priorBypass = npsp.TDTM_TriggerHandler.disableTDTM;
        npsp.TDTM_TriggerHandler.disableTDTM = true;
        try {
            update new Opportunity(Id = opportunityId, Name = desiredName);
        } finally {
            npsp.TDTM_TriggerHandler.disableTDTM = priorBypass;
        }
    }

    /**
     * Credits every household member without sharing. The donor lookup stays in the
     * outer class, so a contact the running user cannot see is rejected; members the
     * user cannot see are still credited, which is what NPSP household soft credit expects.
     */
    private without sharing class GiftWriter {

        public Set<Id> householdContactIds(Id accountId) {
            Set<Id> contactIds = new Set<Id>();
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :accountId
            ]) {
                contactIds.add(member.Id);
            }
            return contactIds;
        }

        public void normalize(
            Id opportunityId,
            Id primaryContactId,
            Set<Id> householdContactIds,
            Decimal amount,
            Date giftDate
        ) {
            ensureContactRoles(opportunityId, primaryContactId, householdContactIds);
            ensureSinglePayment(opportunityId, amount, giftDate);
        }

        private void ensureContactRoles(
            Id opportunityId,
            Id primaryContactId,
            Set<Id> householdContactIds
        ) {
            Set<Id> desiredContactIds = new Set<Id>();
            if (householdContactIds != null) {
                desiredContactIds.addAll(householdContactIds);
            }
            desiredContactIds.add(primaryContactId);
            desiredContactIds.remove(null);

            List<OpportunityContactRole> existing = [
                SELECT Id, ContactId, Role, IsPrimary
                FROM OpportunityContactRole
                WHERE OpportunityId = :opportunityId
                ORDER BY CreatedDate, Id
            ];

            Map<Id, OpportunityContactRole> keeperByContact = new Map<Id, OpportunityContactRole>();
            List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
            for (OpportunityContactRole role : existing) {
                if (!desiredContactIds.contains(role.ContactId) || keeperByContact.containsKey(role.ContactId)) {
                    toDelete.add(role);
                } else {
                    keeperByContact.put(role.ContactId, role);
                }
            }
            if (!toDelete.isEmpty()) {
                delete toDelete;
            }

            List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
            List<OpportunityContactRole> clearPrimary = new List<OpportunityContactRole>();
            List<OpportunityContactRole> assignPrimary = new List<OpportunityContactRole>();

            for (Id memberId : desiredContactIds) {
                Boolean isDonor = memberId == primaryContactId;
                String desiredRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;
                OpportunityContactRole keeper = keeperByContact.get(memberId);
                if (keeper == null) {
                    toInsert.add(new OpportunityContactRole(
                        OpportunityId = opportunityId,
                        ContactId = memberId,
                        Role = desiredRole,
                        IsPrimary = isDonor
                    ));
                    continue;
                }
                if (keeper.Role == desiredRole && keeper.IsPrimary == isDonor) {
                    continue;
                }
                keeper.Role = desiredRole;
                keeper.IsPrimary = isDonor;
                if (isDonor) {
                    assignPrimary.add(keeper);
                } else {
                    clearPrimary.add(keeper);
                }
            }

            // Clear the previous primary before assigning the donor so two roles
            // are never primary in the same DML.
            if (!clearPrimary.isEmpty()) {
                update clearPrimary;
            }
            if (!assignPrimary.isEmpty()) {
                update assignPrimary;
            }
            if (!toInsert.isEmpty()) {
                insert toInsert;
            }

            deleteDuplicateRoles(opportunityId);
        }

        private void deleteDuplicateRoles(Id opportunityId) {
            List<OpportunityContactRole> roles = [
                SELECT Id, ContactId
                FROM OpportunityContactRole
                WHERE OpportunityId = :opportunityId
                ORDER BY CreatedDate, Id
            ];
            Set<Id> seen = new Set<Id>();
            List<OpportunityContactRole> duplicates = new List<OpportunityContactRole>();
            for (OpportunityContactRole role : roles) {
                if (!seen.add(role.ContactId)) {
                    duplicates.add(role);
                }
            }
            if (!duplicates.isEmpty()) {
                delete duplicates;
            }
        }

        private void ensureSinglePayment(Id opportunityId, Decimal amount, Date giftDate) {
            List<npe01__OppPayment__c> payments = [
                SELECT Id,
                       npe01__Payment_Amount__c,
                       npe01__Payment_Date__c,
                       npe01__Scheduled_Date__c,
                       npe01__Paid__c
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
                ORDER BY CreatedDate, Id
            ];

            if (payments.isEmpty()) {
                insert newPayment(opportunityId, null, amount, giftDate);
            } else {
                List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < payments.size(); i++) {
                    extras.add(new npe01__OppPayment__c(Id = payments[i].Id));
                }
                if (!extras.isEmpty()) {
                    delete extras;
                }

                npe01__OppPayment__c keeper = payments[0];
                Boolean keeperCorrect = extras.isEmpty()
                    && keeper.npe01__Paid__c == true
                    && keeper.npe01__Payment_Amount__c == amount
                    && keeper.npe01__Payment_Date__c == giftDate
                    && keeper.npe01__Scheduled_Date__c == giftDate;
                if (!keeperCorrect) {
                    update newPayment(opportunityId, keeper.Id, amount, giftDate);
                }
            }

            // A payment write can cause NPSP to insert another payment from the
            // opportunity trigger. Drop those extras without rewriting the keeper.
            deleteExtraPayments(opportunityId);
        }

        private npe01__OppPayment__c newPayment(
            Id opportunityId,
            Id paymentId,
            Decimal amount,
            Date giftDate
        ) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            if (paymentId == null) {
                payment.npe01__Opportunity__c = opportunityId;
            } else {
                payment.Id = paymentId;
            }
            return payment;
        }

        private void deleteExtraPayments(Id opportunityId) {
            List<npe01__OppPayment__c> payments = [
                SELECT Id
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
                ORDER BY CreatedDate, Id
            ];
            if (payments.size() <= 1) {
                return;
            }
            List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                extras.add(payments[i]);
            }
            delete extras;
        }
    }
}
