public with sharing class FamilyService {
    private static final String PARENT_TYPE = 'Parent';
    private static final String CURRENT_STATUS = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<Id, Id> parentIdByValidChildId = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            parentIdByValidChildId.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }
        if (parentIdByValidChildId.isEmpty()) {
            return;
        }

        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
                AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairKeys.add(pairKey(existing.npe4__Contact__c, existing.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> relationships = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByValidChildId.keySet()) {
            Id parentId = parentIdByValidChildId.get(childId);
            String key = pairKey(childId, parentId);
            if (existingPairKeys.contains(key)) {
                continue;
            }
            // Same unordered pair can appear once in each direction in this map.
            existingPairKeys.add(key);
            // One Parent row from the child. List Setting creates the reciprocal
            // (Son / Daughter / Child) from the child's gender.
            relationships.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = PARENT_TYPE,
                npe4__Status__c = CURRENT_STATUS
            ));
        }

        if (!relationships.isEmpty()) {
            insert relationships;
        }
    }

    private static String pairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);
        return first < second ? first + '-' + second : second + '-' + first;
    }
}
