```apex
/**
 * TDTM handler: creates one thank-you Task when an Opportunity becomes a major gift
 * (Closed Won and Amount >= 5000). Already-qualified gifts are left alone.
 *
 * Register under NPSP Settings > Trigger Configuration (do not add an Apex trigger):
 *   Class OPP_MajorGiftFollowUp_TDTM, Object Opportunity,
 *   Trigger Action AfterInsert;AfterUpdate, Load Order 5, not asynchronous.
 * Deactivating that Trigger Handler record stops this class from running.
 *
 * Issues no SOQL and no DML of its own. Inserts are returned on the TDTM DmlWrapper
 * so the dispatcher performs a single DML statement for the transaction.
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_MINIMUM = 5000;
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;
    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty() || triggerAction == null) {
            return dmlWrapper;
        }
        if (objResult != null && objResult.getSObjectType() != Opportunity.SObjectType) {
            return dmlWrapper;
        }
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Boolean isUpdate = triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;
        // Without prior rows we cannot prove a qualifying transition, so do not insert.
        if (isUpdate && (oldlist == null || oldlist.isEmpty())) {
            return dmlWrapper;
        }

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity currentOpp = (Opportunity) newlist[i];
            Opportunity priorOpp = null;
            if (isUpdate) {
                if (i >= oldlist.size()) {
                    continue;
                }
                priorOpp = (Opportunity) oldlist[i];
            }

            // Insert: prior is null, so a qualifying new gift creates one Task.
            // Update: create only on the transition into qualifying; edits that
            // already qualified (or that leave qualification) do not create another.
            if (isMajorGift(currentOpp) && !isMajorGift(priorOpp)) {
                dmlWrapper.objectsToInsert.add(buildFollowUpTask(currentOpp));
            }
        }

        return dmlWrapper;
    }

    private static Boolean isMajorGift(Opportunity opp) {
        if (opp == null || opp.Amount == null || opp.Amount < MAJOR_GIFT_MINIMUM) {
            return false;
        }
        // IsWon covers the org's closed-won stages in a real trigger context.
        // StageName covers the standard "Closed Won" value when IsWon was not set.
        return opp.IsWon == true || opp.StageName == CLOSED_WON_STAGE;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId
        );
        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_OFFSET_DAYS);
        }
        return followUp;
    }
}
