```apex
/**
 * Returns the subset of record IDs the running user can edit.
 * UserRecordAccess.HasEditAccess accounts for object permissions, ownership,
 * sharing, the role hierarchy, and View All / Modify All.
 */
public with sharing class RecordAccessService {
    // Implementation restriction: a UserRecordAccess query accepts at most 200 record IDs.
    // 2,000 IDs therefore take 10 SOQL queries, inside the 20-query transaction budget.
    private static final Integer MAX_IDS_PER_QUERY = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();
        List<Id> chunk = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId == null) {
                continue;
            }
            chunk.add(recordId);
            if (chunk.size() == MAX_IDS_PER_QUERY) {
                editable.addAll(queryEditableIds(runningUserId, chunk));
                chunk = new List<Id>();
            }
        }
        if (!chunk.isEmpty()) {
            editable.addAll(queryEditableIds(runningUserId, chunk));
        }
        return editable;
    }

    private static Set<Id> queryEditableIds(Id userId, List<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        // HasEditAccess is not filterable; evaluate it in Apex.
        for (UserRecordAccess accessRow : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :userId
              AND RecordId IN :recordIds
        ]) {
            if (accessRow.HasEditAccess == true) {
                editable.add(accessRow.RecordId);
            }
        }
        return editable;
    }
}
