public inherited sharing class AccountOwnershipService {
    /**
     * Sets OwnerId on the given Accounts and on every Contact of those Accounts.
     * Account trigger actions are bypassed for this ownership change only.
     * Contact trigger actions run normally. The Account bypass is cleared
     * before returning, including when DML throws, so later Account automation
     * in the same transaction behaves normally.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Whole-sObject transaction bypass: no Account trigger action runs.
        TriggerBase.bypass(Account.SObjectType);
        try {
            List<Account> accounts = new List<Account>();
            for (Id accountId : accountIds) {
                accounts.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
            // All-or-none. Exceptions propagate to the caller unchanged.
            Database.update(accounts, true);

            List<Contact> contacts = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];
            for (Contact contactRecord : contacts) {
                contactRecord.OwnerId = newOwnerId;
            }
            Database.update(contacts, true);
        } finally {
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
