/**
 * DML-less tests for TA_Opportunity_GuardAmountDecrease.
 * Records are built in memory and beforeUpdate is invoked directly, as TAF recommends.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    private static void reductionOfMoreThanHalfIsRejected() {
        Opportunity updated = runBeforeUpdate(1000, 499);

        Assert.isTrue(updated.hasErrors(), 'Reducing Amount from 1000 to 499 must be rejected.');
        Assert.areEqual(
            1,
            updated.getErrors().size(),
            'Expected exactly one error when Amount is reduced by more than half.'
        );
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            updated.getErrors()[0].getMessage(),
            'Expected the guard error message.'
        );
    }

    @IsTest
    private static void reductionOfExactlyHalfIsAccepted() {
        Opportunity updated = runBeforeUpdate(1000, 500);

        assertAccepted(updated);
    }

    @IsTest
    private static void increaseIsAccepted() {
        Opportunity updated = runBeforeUpdate(1000, 1500);

        assertAccepted(updated);
    }

    @IsTest
    private static void nullPreviousAmountIsAccepted() {
        Opportunity updated = runBeforeUpdate(null, 100);

        assertAccepted(updated);
    }

    @IsTest
    private static void onlyViolatingRecordsAreRejected() {
        Id rejectedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id exactlyHalfId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id smallerDecreaseId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id increasedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id nullPreviousId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id alsoRejectedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity rejected = new Opportunity(Id = rejectedId, Amount = 499);
        Opportunity exactlyHalf = new Opportunity(Id = exactlyHalfId, Amount = 500);
        Opportunity smallerDecrease = new Opportunity(Id = smallerDecreaseId, Amount = 750);
        Opportunity increased = new Opportunity(Id = increasedId, Amount = 1500);
        Opportunity nullPrevious = new Opportunity(Id = nullPreviousId, Amount = 100);
        Opportunity alsoRejected = new Opportunity(Id = alsoRejectedId, Amount = 999);

        List<Opportunity> triggerNew = new List<Opportunity>{
            rejected,
            exactlyHalf,
            smallerDecrease,
            increased,
            nullPrevious,
            alsoRejected
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = rejectedId, Amount = 1000),
            new Opportunity(Id = exactlyHalfId, Amount = 1000),
            new Opportunity(Id = smallerDecreaseId, Amount = 1000),
            new Opportunity(Id = increasedId, Amount = 1000),
            new Opportunity(Id = nullPreviousId, Amount = null),
            new Opportunity(Id = alsoRejectedId, Amount = 2000)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        assertRejected(rejected);
        assertAccepted(exactlyHalf);
        assertAccepted(smallerDecrease);
        assertAccepted(increased);
        assertAccepted(nullPrevious);
        assertRejected(alsoRejected);
    }

    private static Opportunity runBeforeUpdate(Decimal previousAmount, Decimal newAmount) {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity updated = new Opportunity(Id = oppId, Amount = newAmount);
        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(
                new List<Opportunity>{ updated },
                new List<Opportunity>{ new Opportunity(Id = oppId, Amount = previousAmount) }
            );
        return updated;
    }

    private static void assertRejected(Opportunity opp) {
        Assert.isTrue(opp.hasErrors(), 'Expected the opportunity to be rejected.');
        Assert.areEqual(1, opp.getErrors().size(), 'Expected exactly one error.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            opp.getErrors()[0].getMessage(),
            'Expected the guard error message.'
        );
    }

    private static void assertAccepted(Opportunity opp) {
        Assert.isFalse(opp.hasErrors(), 'Expected the opportunity to be accepted.');
        Assert.areEqual(0, opp.getErrors().size(), 'Expected no errors on an accepted opportunity.');
    }
}
