/**
 * Blocks Contacts that would share an email address (case-insensitive) with another
 * Contact on the same Account. Contacts with no Account or no Email are ignored.
 * On update, only Email or AccountId changes are checked, so legacy duplicates do
 * not block unrelated edits, and a Contact never conflicts with itself.
 *
 * Runs without sharing so a user who cannot see the other Contact cannot bypass the rule.
 */
public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String DUPLICATE_EMAIL_ERROR = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicateEmails(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        preventDuplicateEmails(triggerNew, triggerOld);
    }

    private void preventDuplicateEmails(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> idsBeingChecked = new Set<Id>();

        for (Integer index = 0; index < triggerNew.size(); index++) {
            Contact newContact = (Contact) triggerNew[index];
            if (!hasAccountAndEmail(newContact)) {
                continue;
            }
            if (triggerOld != null && !emailOrAccountChanged(newContact, (Contact) triggerOld[index])) {
                continue;
            }
            contactsToCheck.add(newContact);
            accountIds.add(newContact.AccountId);
            emails.add(newContact.Email);
            if (newContact.Id != null) {
                idsBeingChecked.add(newContact.Id);
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Existing rows are claimed first so they always win over records in this save.
        // Ids being checked are skipped so a Contact does not conflict with itself and so
        // a record moving off an email does not block another record moving onto it.
        Map<Id, Set<String>> takenEmailsByAccount = new Map<Id, Set<String>>();
        for (Contact existingContact : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails
        ]) {
            if (idsBeingChecked.contains(existingContact.Id) || !hasAccountAndEmail(existingContact)) {
                continue;
            }
            claimEmail(takenEmailsByAccount, existingContact.AccountId, existingContact.Email);
        }

        for (Contact contactToCheck : contactsToCheck) {
            Boolean isFirstUse = claimEmail(
                takenEmailsByAccount,
                contactToCheck.AccountId,
                contactToCheck.Email
            );
            if (!isFirstUse) {
                contactToCheck.addError(DUPLICATE_EMAIL_ERROR);
            }
        }
    }

    private static Boolean hasAccountAndEmail(Contact contact) {
        return contact.AccountId != null && String.isNotBlank(contact.Email);
    }

    private static Boolean emailOrAccountChanged(Contact newContact, Contact oldContact) {
        return newContact.Email != oldContact.Email || newContact.AccountId != oldContact.AccountId;
    }

    /**
     * @return true when this account/email pair was not already taken.
     *         Email is compared case-insensitively. Caller order is preserved,
     *         so the first record in the save wins and each later one loses.
     */
    private static Boolean claimEmail(Map<Id, Set<String>> takenEmailsByAccount, Id accountId, String email) {
        Set<String> takenEmails = takenEmailsByAccount.get(accountId);
        if (takenEmails == null) {
            takenEmails = new Set<String>();
            takenEmailsByAccount.put(accountId, takenEmails);
        }
        return takenEmails.add(email.toLowerCase());
    }
}
